SELECT COUNT(*)
  FROM app_user
 WHERE email = #{_parameter}

mapper.update:
UPDATE app_user
   SET persona = #{persona,jdbcType=VARCHAR}
 WHERE user_id = #{userId,jdbcType=NUMERIC}
   AND status = 'ACTIVE'
   AND deleted_at IS NULL

UPDATE app_user
   SET country_id = #{countryId,jdbcType=NUMERIC},
       preferred_language_code = #{languageCode,jdbcType=VARCHAR}
 WHERE user_id = #{userId,jdbcType=NUMERIC}
   AND status = 'ACTIVE'
   AND deleted_at IS NULL
